values('TRANSACTIONS_ANNUAL_COUNT','Operaciones anuales declaradas','BUSINESS_ACTIVITY','COUNT','transactions',null,'SAME_METRIC',true,'Número de operaciones/transacciones declarado para una ventana anual. No equivale a volumen monetario.',24)
on conflict(metric_code) do update set label=excluded.label,dimension=excluded.dimension,unit_kind=excluded.unit_kind,default_unit=excluded.default_unit,default_currency=excluded.default_currency,comparable_scope=excluded.comparable_scope,higher_means_more_weight=excluded.higher_means_more_weight,description=excluded.description,sort_order=excluded.sort_order;

with vals(fintech_id,business_model,target_customer,revenue_model,bm_conf,tc_conf,rev_conf,bm_basis,tc_basis,rev_basis,source_url) as (
 values
 ('ENT-RUT-76917781-7','B2B','EMPRESAS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Flow es una plataforma/pasarela de pagos y recaudación para comercios y negocios, con API, botón de pago, POS, pagos recurrentes y múltiples medios de pago.','Flow cobra el servicio a quien recibe el dinero y ofrece condiciones especiales para empresas/comercios según volumen.','Las tarifas vigentes cobran una tasa por transacción al comercio/receptor, con tasas diferenciadas por medio de pago y plazo de abono.','https://web.flow.cl/es-cl/tarifas/'),
 ('ENT-RUT-78008316-6','B2B','EMPRESAS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Hpay centraliza medios de pago online para negocios y emprendimientos mediante app, links de pago y cobros digitales.','La comunicación vigente está dirigida explícitamente a negocios y emprendimientos que necesitan cobrar y organizar sus ventas.','Hpay publica una comisión de 2,0% + IVA por transacción para los medios de pago observados.','https://hpay.cl/tarifas'),
 ('ENT-RUT-76974041-4','B2B2C','AMBOS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Vita Wallet combina billetera/remesas internacionales para personas con cuentas empresa, pagos a proveedores, nómina, API, enlaces de pago y operaciones cripto.','Los términos y productos vigentes admiten personas naturales y jurídicas y existe una oferta empresarial específica.','Vita cobra comisiones por operación, normalmente integradas en la tasa de cambio, y declara ausencia de suscripción o mensualidad.','https://vitawallet.io/limites-y-comisiones/'),
 ('ENT-RUT-76945003-3','B2B','EMPRESAS',null,0.999::numeric,0.999::numeric,null,'UPago es una plataforma de pagos, cobranzas y aseguramiento de ingresos para empresas, con recaudación, cuentas vencidas y automatización de pagos.','La oferta vigente se dirige explícitamente a empresas que buscan automatizar pagos, cobros, facturas y recaudación.','La evidencia pública revisada describe el servicio y su automatización, pero no permite asignar de forma responsable un único modelo de monetización.','https://www.upago.cl/es/'),
 ('ENT-RUT-59121440-3','B2B2C','AMBOS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Mercado Pago es un ecosistema multivehículo que ofrece cuenta digital y tarjeta para personas y soluciones de cobro, Point, crédito y pagos para comercios.','La oferta Chile observada atiende simultáneamente usuarios personas y comercios/negocios mediante productos diferenciados.','Los productos de cobro Point y sellers cobran comisiones porcentuales sobre ventas; se registra comisión transaccional como mecanismo observable principal del negocio de pagos, sin representar toda la economía del grupo.','https://www.mercadopago.cl/herramientas-para-vender/lectores-point'),
 ('ENT-RUT-76901962-6','B2B2C','AMBOS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Retorna combina remesas digitales para personas con una plataforma B2B/API para pagos masivos, remesas, FX y on/off-ramp con stablecoins.','La oferta actual incluye usuarios personas y empresas que integran pagos/remesas mediante API o archivos masivos.','Retorna informa costos/comisiones por operación; para dólares digitales cobra una comisión de adquisición/conversión comunicada antes de confirmar la operación.','https://www.retorna.app/es/terminos-y-condiciones/billetera-en-dolares-digitales')
), logged as (
 select v.fintech_id,'MANUAL_OFFICIAL_PAYMENTS_II_2026_09_09',v.business_model,v.bm_conf,v.target_customer,v.tc_conf,v.revenue_model,v.rev_conf,1,now(),jsonb_build_object('source_url',v.source_url,'business_model_basis',v.bm_basis,'target_customer_basis',v.tc_basis,'revenue_model_basis',v.rev_basis,'manual_validation',true,'cohort','PAYMENTS_REMITTANCES_II') from vals v returning fintech_id
)
update public.aml_fintech_entity e
set business_model=v.business_model,target_customer=v.target_customer,revenue_model=v.revenue_model,business_model_basis=v.bm_basis,business_model_confidence=v.bm_conf,target_customer_basis=v.tc_basis,target_customer_confidence=v.tc_conf,revenue_model_basis=v.rev_basis,revenue_model_confidence=v.rev_conf,profile_classifier_version='MANUAL_OFFICIAL_PAYMENTS_II_2026_09_09',profile_refreshed_at=now(),refreshed_at=now()
from vals v where e.fintech_id=v.fintech_id and exists(select 1 from logged l where l.fintech_id=e.fintech_id);

on conflict(observation_key) do update set evidence_status=excluded.evidence_status,evidence_class=excluded.evidence_class,confidence=excluded.confidence,basis=excluded.basis,source_code=excluded.source_code,source_url=excluded.source_url,evidence_excerpt=excluded.evidence_excerpt,last_seen_at=now(),observed_at=excluded.observed_at;

on conflict(observation_key) do update set value_numeric=excluded.value_numeric,value_text=excluded.value_text,qualifier=excluded.qualifier,evidence_type=excluded.evidence_type,confidence=excluded.confidence,source_url=excluded.source_url,observed_at=excluded.observed_at,basis=excluded.basis,evidence_excerpt=excluded.evidence_excerpt,metadata=excluded.metadata,last_seen_at=now();

